# Sample parameters and generates msABC string
# @description this function sample parameters from priors and trasform them to coalescent scale to generate a msABC command from a model object generated by the Model Builder, main.menu() function.
# @param model A model object.
# @param use.alpha Logical.If TRUE the most recent population size change will be exponential. If FALSE sudden demographic changes.
# @return a list with msABC command and sampled parameters.
# @note This function is used internally for the sim.msABC function. One mey want to run this function to check the msABC string.
#
msABC.commander<-function(model,use.alpha=NULL,arg){

  # Resolve use.alpha: explicit argument > model field
  if (is.null(use.alpha)) {
    if (is.null(model$use.alpha))
      stop("model$use.alpha is missing. Set it on the model (e.g. model$use.alpha <- FALSE).")
    use.alpha <- model$use.alpha
  }

  # empty parameter vector
  parameters<-vector()

  # bind Ne, mig and Time priors
  size.pars<-rbind(model$flags$n,model$flags$en$size)
  mig.pars<-rbind(model$flags$m,model$flags$em$size)
  time.pars<-rbind(model$flags$ej,model$flags$en$time,model$flags$em$time)

  # sample Ne, div.time and mutation rate
  size.pars<-PipeMaster:::sample.w.cond(par.matrix=size.pars,
    cond.list=model$conds$size)
  # bind Ne sampled parameters
  parameters<-rbind(parameters,size.pars[,c(1,4)])

  if(is.null(time.pars)==F){
    time.pars<-PipeMaster:::sample.w.cond(par.matrix=time.pars,
      cond.list=model$conds$time)
    # bind sampled time parameters
    parameters<-rbind(parameters,time.pars[,c(1,4)])
  }

  loci<-model$loci

  # sample migrations if present and bind sampled parameters
  if(is.null(mig.pars)==F){
    mig.pars<-sample.w.cond(par.matrix=mig.pars,
      cond.list=model$conds$mig)
    #bind sampled migration parameters
    parameters<-rbind(parameters,mig.pars[,c(1,4)])
  }

  #### bind sampled mutation rate
  #parameters<-parameters#,loci[,c(1,4)])

  ####### Ancestral Ne at join events #####################################
  # Set t.Ne.anc_X_Y = joinX_Y time; optionally overwrite Ne.anc = sum daughters
  #
  # Ne.anc_X_Y parameters are created by the model builder for each -ej node.
  # The surviving pop (Y) gets an -en at join time with this ancestral Ne.
  # When sum_anc_ne is TRUE, Ne.anc = sum of daughter Ne at join time.
  #
  # A join may have NO Ne.anc_X_Y row (GUI: "survivor keeps its current Ne",
  # PM-KEEPSURV-20260925). Then no -en is emitted at that join and survivor Y
  # keeps its own size AND growth rate through it (-en would zero growth;
  # -ej leaves both untouched in msABC and scrm). The sum rule still applies
  # at the other joins; a later sum reads such a survivor through ne_at(),
  # i.e. its latest Ne0/NeK STEP value, not its value on the growth curve.

  # Build a lookup: pop pair "X Y" -> ej row index (handles both joinX_Y and joinX naming)
  if (is.null(time.pars)) { ej_rows <- integer(0) } else
  ej_rows <- which(time.pars[, 2] == "-ej")
  ej_lookup <- list()  # keyed by "X_Y" -> row in time.pars
  if (length(ej_rows) > 0) {
    for (er in ej_rows) {
      # ej column 3 has the pair "X Y" -- extract from time.pars
      # But time.pars is rbind(ej, en$time, em$time), so ej rows still have col 3
      ej_pair_str <- time.pars[er, 3]
      ej_pair <- strsplit(ej_pair_str, " ")[[1]]
      key <- paste(ej_pair, collapse = "_")
      ej_lookup[[key]] <- er
    }
  }

  anc_idx <- grep("^Ne\\.anc_", size.pars[, 1])
  if (length(anc_idx) > 0 && length(ej_lookup) > 0) {
    # Sort by join time (earliest first) so inner joins are computed before outer ones
    anc_join_times <- sapply(anc_idx, function(ai) {
      pair_key <- sub("^Ne\\.anc_", "", size.pars[ai, 1])
      join_row <- ej_lookup[[pair_key]]
      if (length(join_row) == 1) as.numeric(time.pars[join_row, 4]) else Inf
    })
    anc_idx <- anc_idx[order(anc_join_times)]
    # which Ne.anc rows already hold a COMPUTED sum (PM-SUMANC-20260912)
    anc_done <- setNames(rep(FALSE, length(anc_idx)), as.character(anc_idx))
    for (ai in anc_idx) {
      # Extract pair from name: Ne.anc_1_2 -> c("1", "2")
      pair <- strsplit(sub("^Ne\\.anc_", "", size.pars[ai, 1]), "_")[[1]]
      pair_key <- paste(pair, collapse = "_")
      time_anc_name <- paste0("t.Ne.anc_", pair_key)

      # Find matching join row by pair key
      join_row <- ej_lookup[[pair_key]]
      time_anc_row <- which(time.pars[, 1] == time_anc_name)

      if (length(join_row) == 1 && length(time_anc_row) == 1) {
        # Set ancestral Ne time = join time
        time.pars[time_anc_row, 4:5] <- time.pars[join_row, 4:5]
        # Also update in parameters
        par_time_row <- which(parameters[, 1] == time_anc_name)
        if (length(par_time_row) == 1)
          parameters[par_time_row, 2] <- time.pars[join_row, 4]
      }

      # Sum daughter Ne if model$sum_anc_ne is TRUE
      #
      # PM-SUMANC-20260912: two fixes.
      # (1) Only Ne.anc rows ALREADY COMPUTED in an earlier iteration may be
      #     used as a daughter's "most recent Ne". Previously any Ne.anc row
      #     was accepted, so a row still holding its prior-sampled value could
      #     leak in -- silently, since the result still looked plausible.
      # (2) Joins into the SAME survivor at the SAME time are one simultaneous
      #     merge, not a predecessor relation. They are handled as a group: the
      #     ancestral Ne is the survivor's pre-join Ne plus ALL joining
      #     daughters, and every row in the group receives that same total, so
      #     the result does not depend on the order the -en flags are emitted.
      if (isTRUE(model$sum_anc_ne) && length(join_row) == 1) {
        join_time <- as.numeric(time.pars[join_row, 4])
        survivor  <- pair[2]

        # every Ne.anc row that merges into this survivor at this same time
        grp <- anc_idx[vapply(anc_idx, function(gi) {
          gp <- strsplit(sub("^Ne\\.anc_", "", size.pars[gi, 1]), "_")[[1]]
          gj <- ej_lookup[[paste(gp, collapse = "_")]]
          length(gj) == 1 && gp[2] == survivor &&
            isTRUE(all.equal(as.numeric(time.pars[gj, 4]), join_time))
        }, logical(1))]

        # most recent Ne of `pop_id` STRICTLY BEFORE join_time
        ne_at <- function(pop_id) {
          val <- NA_real_; best_time <- -Inf
          ne0_row <- which(size.pars[, 1] == paste0("Ne0.pop", pop_id))
          if (length(ne0_row) == 1) { val <- as.numeric(size.pars[ne0_row, 4]); best_time <- 0 }
          ne_rows <- setdiff(grep(paste0("^Ne[0-9]+\\.pop", pop_id, "$"), size.pars[, 1]), ne0_row)
          for (nr in ne_rows) {
            t_row <- which(time.pars[, 1] == paste0("t.", size.pars[nr, 1]))
            if (length(t_row) == 1) {
              nt <- as.numeric(time.pars[t_row, 4])
              if (nt <= join_time && nt >= best_time) {
                val <- as.numeric(size.pars[nr, 4]); best_time <- nt
              }
            }
          }
          for (ar in grep(paste0("^Ne\\.anc_.*_", pop_id, "$"), size.pars[, 1])) {
            if (!anc_done[as.character(ar)]) next          # (1) computed rows only
            arj <- ej_lookup[[sub("^Ne\\.anc_", "", size.pars[ar, 1])]]
            if (length(arj) != 1) next
            at <- as.numeric(time.pars[arj, 4])
            if (at < join_time && at >= best_time) {       # (2) strictly earlier
              val <- as.numeric(size.pars[ar, 4]); best_time <- at
            }
          }
          val
        }

        daughters <- vapply(grp, function(gi)
          strsplit(sub("^Ne\\.anc_", "", size.pars[gi, 1]), "_")[[1]][1], "")
        sum_ne <- ne_at(survivor) + sum(vapply(daughters, ne_at, 0))

        for (gi in grp) {
          size.pars[gi, 4:5] <- sum_ne
          par_ne_row <- which(parameters[, 1] == size.pars[gi, 1])
          if (length(par_ne_row) == 1) parameters[par_ne_row, 2] <- sum_ne
          anc_done[as.character(gi)] <- TRUE
        }
      }
    }
  }

  ####### End of parameter sampling #######################################
  #########################################################################

  ####### Generate ms string ##############################################
  ####### Convertion to coalescent scale #####################################

  # generate coalescent scalar. Arbitrary value.

  #### if single population
  # if(model$I[1,3]=="1"){
  #   Ne0<-as.numeric(size.pars[1,4])
  #   ms.scalar<-4*Ne0
  #  } else {
  #  Ne0<-mean(as.numeric(model$flags$n[,4:5]))
  #  ms.scalar<-4*Ne0
  # }
  Ne0 <- 100000
  ms.scalar <- 4*Ne0

  # rescale to inheritance scalar and transform size parameters to relative to Ne0
  size.pars[,4:5] <- as.numeric(size.pars[,4])/Ne0

  #### bind scaled theta per gene (4Ne0*m*pb)
  # loci<-cbind(loci,ms.scalar*as.numeric(loci[,4])*as.numeric(loci[,2]))

  #### convertion of time to coalescent scale
  time.pars[,4:5] <- as.numeric(time.pars[,4])/ms.scalar

  commands <- list(NULL,NULL)
  #### ms string command
  mig_scale <- if (!is.null(model$mig_scale)) model$mig_scale else "Nm"
  string <- PipeMaster:::ms.string.generator(model, size.pars, mig.pars,time.pars, use.alpha=use.alpha, scalar = as.numeric(loci[1,3]), mig_scale = mig_scale)
  #################################### theta and structure ###########################
  ######### generate -t and -I part of the command
  y <- paste(sum(as.numeric(model$I[1,4:ncol(model$I)])),1,paste(model$I[1,2:ncol(model$I)],collapse=" "),collapse=" ")
  ######### generate locfile part of the command
  loc.string <- paste("--frag-begin --finp .",arg,"locfile.txt --N ",Ne0," --frag-end",sep="")

  if(model$I[1, 3]=="1"){
    string <- gsub("-n 1","-en 0 1", string)
  }

  #### final command
  commands[[1]] <- paste(y,string,loc.string, collapse=" ")

  #### attach sampled parameters
  commands[[2]] <- t(parameters)
  return(commands)
  }

